import re as _re
def _slug(t):
    t = t.lower(); t = _re.sub(r'[àâä]', 'a', t); t = _re.sub(r'[éèêë]', 'e', t); t = _re.sub(r'[îï]', 'i', t); t = _re.sub(r'[ôö]', 'o', t); t = _re.sub(r'[ùûü]', 'u', t); t = t.replace('ç', 'c')
    return _re.sub(r'[^a-z0-9]+', '-', t).strip('-')[:90].rstrip('-')
corr_gen.slug = _slug   # intitulés complets, pas de troncature à 60 caractères

